-- Arbeitsrecht Berufsbildung > Wirtschaftliche Zusammenhänge > Globalisierung > Handelsabkommen
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Fördern Handelsabkommen den Export von IT-Dienstleistungen eines IT-Betriebs?', 2, '[{"text": "Ja", "correct": true, "because": "Handelsabkommen reduzieren Handelsbarrieren"}, {"text": "Nein", "correct": false, "because": "Export wird erleichtert"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Handelsabkommen die Kosten für einen IT-Betrieb durch Zollreduktion senken?', 2, '[{"text": "Ja", "correct": true, "because": "Zollreduktion senkt Importkosten"}, {"text": "Nein", "correct": false, "because": "Kostenreduktion ist ein Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Erhöhen Handelsabkommen den Wettbewerb für einen IT-Betrieb auf internationalen Märkten?', 2, '[{"text": "Ja", "correct": true, "because": "Offene Märkte fördern Konkurrenz"}, {"text": "Nein", "correct": false, "because": "Wettbewerb steigt durch Abkommen"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Handelsabkommen für einen IT-Betrieb mit rechtlichen Einschränkungen verbunden?', 2, '[{"text": "Ja", "correct": true, "because": "Abkommen können Regeln und Standards vorschreiben"}, {"text": "Nein", "correct": false, "because": "Rechtliche Vorgaben sind üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Handelsabkommen einem IT-Betrieb den Zugang zu neuen Technologien erleichtern?', 2, '[{"text": "Ja", "correct": true, "because": "Abkommen fördern Technologieaustausch"}, {"text": "Nein", "correct": false, "because": "Technologiezugriff wird erleichtert"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welchen Vorteil bieten Handelsabkommen einem IT-Betrieb?', 2, '[{"text": "Reduzierte Handelsbarrieren", "correct": true, "because": "Abkommen senken Zölle und Vorschriften"}, {"text": "Höhere Steuerlast", "correct": false, "because": "Kein Vorteil"}, {"text": "Weniger Wettbewerb", "correct": false, "because": "Wettbewerb steigt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein typischer Effekt von Handelsabkommen auf einen IT-Betrieb?', 3, '[{"text": "Erleichterter Marktzugang", "correct": true, "because": "Abkommen öffnen Märkte"}, {"text": "Geringere Nachfrage", "correct": false, "because": "Nachfrage kann steigen"}, {"text": "Höhere Produktionskosten", "correct": false, "because": "Kosten können sinken"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Nachteil kann durch Handelsabkommen für einen IT-Betrieb entstehen?', 3, '[{"text": "Erhöhter Wettbewerbsdruck", "correct": true, "because": "Offene Märkte fördern Konkurrenz"}, {"text": "Geringere Exportmöglichkeiten", "correct": false, "because": "Export wird erleichtert"}, {"text": "Einfachere Rechtsprechung", "correct": false, "because": "Recht kann komplexer werden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgen Handelsabkommen für einen IT-Betrieb?', 2, '[{"text": "Förderung des internationalen Handels", "correct": true, "because": "Abkommen öffnen Märkte"}, {"text": "Erhöhung der Steuerlast", "correct": false, "because": "Kein Ziel"}, {"text": "Reduktion der Innovation", "correct": false, "because": "Innovation wird gefördert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielen Handelsabkommen für den globalen Erfolg eines IT-Betriebs?', 3, '[{"text": "Sie erleichtern den Markteintritt", "correct": true, "because": "Abkommen reduzieren Barrieren"}, {"text": "Sie erhöhen die Produktionskosten", "correct": false, "because": "Kosten können sinken"}, {"text": "Sie reduzieren den Wettbewerb", "correct": false, "because": "Wettbewerb steigt"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten Handelsabkommen einem IT-Betrieb?', 4, '[{"text": "Reduzierte Zölle", "correct": true, "because": "Senkt Importkosten"}, {"text": "Erleichterter Marktzugang", "correct": true, "because": "Öffnet internationale Märkte"}, {"text": "Höhere Steuerlast", "correct": false, "because": "Kein Vorteil"}, {"text": "Technologieaustausch", "correct": true, "because": "Fördert Innovation"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile können Handelsabkommen für einen IT-Betrieb mit sich bringen?', 3, '[{"text": "Erhöhter Wettbewerbsdruck", "correct": true, "because": "Offene Märkte fördern Konkurrenz"}, {"text": "Rechtliche Anpassungen", "correct": true, "because": "Neue Vorschriften nötig"}, {"text": "Geringere Nachfrage", "correct": false, "because": "Nachfrage kann steigen"}, {"text": "Komplexere Standards", "correct": true, "because": "Harmonisierung kann Aufwand erhöhen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren fördern den Nutzen von Handelsabkommen für einen IT-Betrieb?', 4, '[{"text": "Zollreduktion", "correct": true, "because": "Senkt Kosten"}, {"text": "Marktöffnung", "correct": true, "because": "Erweitert Kundenbasis"}, {"text": "Hohe Transportkosten", "correct": false, "because": "Kein Vorteil bei IT"}, {"text": "Harmonisierte Standards", "correct": true, "because": "Vereinfacht Handel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Auswirkungen haben Handelsabkommen auf einen IT-Betrieb?', 3, '[{"text": "Erleichterter Export", "correct": true, "because": "Weniger Barrieren"}, {"text": "Gesteigerter Wettbewerb", "correct": true, "because": "Mehr Konkurrenten"}, {"text": "Höhere lokale Steuern", "correct": false, "because": "Steuern nicht direkt betroffen"}, {"text": "Zugang zu neuen Märkten", "correct": true, "because": "Abkommen öffnen Märkte"}]'),
('00000000-0000-0000-0000-000000000000', 'Was unterscheidet Handelsabkommen von freiem Handel ohne Abkommen für einen IT-Betrieb?', 3, '[{"text": "Abkommen reduzieren Zölle gezielt", "correct": true, "because": "Vertraglich geregelt"}, {"text": "Abkommen schaffen einheitliche Standards", "correct": true, "because": "Harmonisierung möglich"}, {"text": "Freier Handel ist immer kostengünstiger", "correct": false, "because": "Abkommen senken Kosten gezielt"}, {"text": "Abkommen fördern den Marktzugang", "correct": true, "because": "Regeln erleichtern Eintritt"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Handelsabkommen fördern den Export von IT-Dienstleistungen. b) Handelsabkommen reduzieren den Wettbewerb.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Export ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Handelsabkommen senken Zölle für einen IT-Betrieb. b) Handelsabkommen erhöhen die Kosten durch Wettbewerb.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zölle ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Handelsabkommen erleichtern den Marktzugang für einen IT-Betrieb. b) Handelsabkommen haben keine rechtlichen Auswirkungen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Marktzugang ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Handelsabkommen fördern den Technologieaustausch für einen IT-Betrieb. b) Handelsabkommen reduzieren die Nachfrage nach IT-Dienstleistungen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Technologie ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Handelsabkommen erhöhen den Wettbewerbsdruck für einen IT-Betrieb. b) Handelsabkommen bieten keine Kostenvorteile.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Wettbewerb ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

